WITH with_windows AS (SELECT *, LEAD(amount, 2) OVER w_recent AS next_amount, AVG(amount) OVER (ORDER BY paid_at, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS amount_avg_5_prior, LAST_VALUE(amount) IGNORE NULLS OVER (ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_amount, ROUND(amount / SUM(amount) OVER (PARTITION BY status), 4) AS amount_share FROM payments WINDOW w_recent AS (PARTITION BY order_id ORDER BY amount, id)) SELECT s.id, s.order_id, s.method, s.status, s.next_amount, s.amount_avg_5_prior, (SELECT MAX(t2.amount) FROM payments t2 WHERE t2.order_id = s.order_id) AS max_payment_amount FROM with_windows s ORDER BY id DESC LIMIT 5
